<script setup lang="ts">
import { reactive,ref,onMounted,onBeforeUnmount } from 'vue';import { ElButton } from 'element-plus';import { useDesktop } from './store.ts';import { eventKinds,eventReasons } from '../../../packages/contracts/stage3.ts';
const store=useDesktop(),form=reactive({from:'',to:'',type:'',reason:''}),items=ref<Array<{sequence:number;at:string;type:string;reason:string}>>([]),cursor=ref<string|null>(null),boundary=ref<number|null>(null),operations=ref<Array<{id:string;state:string;written:number;fileName:string|null;error:string|null}>>([]),busy=ref(false),message=ref('');let timer:ReturnType<typeof setTimeout>|undefined,active=true;let filter:Record<string,unknown>={};
function queryFilter(){return {...(form.from?{from:new Date(form.from).toISOString()}:{}),...(form.to?{to:new Date(form.to).toISOString()}:{}),...(form.type?{type:form.type}:{}),...(form.reason?{reason:form.reason}:{})};}
async function query(next=false){busy.value=true;message.value='';try{if(!next)filter=queryFilter();const value=await store.request('events.query',{...filter,limit:20,...(next&&cursor.value?{cursor:cursor.value}:{})});items.value=value.items as typeof items.value;cursor.value=value.nextCursor as string|null;boundary.value=Number(value.boundary);}catch(cause){message.value=(cause as Error).message;items.value=[];cursor.value=null;}finally{busy.value=false;}}
async function exportHistory(){message.value='';try{const value=await store.request('events.export',queryFilter(),crypto.randomUUID());message.value='导出已接受：'+value.id;await poll();}catch(cause){message.value=(cause as Error).message;}}
async function cancel(id:string){try{await store.request('operations.cancel',{id},crypto.randomUUID());await poll();}catch(cause){message.value=(cause as Error).message;}}
async function poll(){try{const value=await store.request('operations.list',{});if(active)operations.value=(value.items as Array<Record<string,unknown>>).filter(x=>x.kind==='events.export') as typeof operations.value;}catch(cause){if(active)message.value=(cause as Error).message;}clearTimeout(timer);if(active)timer=setTimeout(()=>{void poll();},1000);}
onMounted(()=>{void query();void poll();});onBeforeUnmount(()=>{active=false;clearTimeout(timer);});
</script>
<template><section class="panel"><div class="section-heading"><h2>本应用历史</h2><span class="muted">固定边界 {{ boundary??'未读取' }}</span></div><p class="muted">记录实际运行、设置和导出事实；不包含聊天、账号、真实额度或 Goal 正文。任务归档与时间线可在任务页面查看。</p><div class="form-grid"><label>开始时间（本机）<input v-model="form.from" aria-label="历史开始时间" type="datetime-local" /></label><label>结束时间（本机）<input v-model="form.to" aria-label="历史结束时间" type="datetime-local" /></label><label>事件类型<select v-model="form.type" aria-label="历史事件类型"><option value="">全部</option><option v-for="type in eventKinds" :key="type">{{ type }}</option></select></label><label>原因<select v-model="form.reason" aria-label="历史原因"><option value="">全部</option><option v-for="reason in eventReasons" :key="reason">{{ reason }}</option></select></label></div><div class="actions"><ElButton type="primary" :disabled="busy" @click="query()">查询历史</ElButton><ElButton :disabled="busy||!cursor" @click="query(true)">下一页历史</ElButton><ElButton @click="exportHistory">导出当前条件 JSONL</ElButton></div><p v-if="message" role="status" class="notice">{{ message }}</p><div class="table-scroll"><table v-if="items.length"><thead><tr><th>序号 / 时间</th><th>事实</th><th>原因</th></tr></thead><tbody><tr v-for="item in items" :key="item.sequence"><td>{{ item.sequence }}<small>{{ new Date(item.at).toLocaleString() }}</small></td><td>{{ item.type }}</td><td>{{ item.reason }}</td></tr></tbody></table></div><p v-if="!items.length&&!busy" class="muted">当前边界无匹配事件。</p></section><section class="panel"><h2>本机导出操作（桌面管理视图）</h2><p class="muted">文件写入本 profile 的固定 exports 目录，不覆盖既有文件。关闭页面不取消导出；明确退出会取消未完成操作。</p><ul class="check-list"><li v-for="operation in operations" :key="operation.id"><div><strong>{{ operation.state }} · {{ operation.written }} 条</strong><span class="muted mono">{{ operation.fileName||operation.error||operation.id }}</span></div><ElButton v-if="['accepted','running'].includes(operation.state)" @click="cancel(operation.id)">取消导出</ElButton></li></ul><p v-if="!operations.length" class="muted">暂无本用户发起的导出。</p><ElButton @click="store.request('desktop.openDataDirectory').catch(cause=>message=cause.message)">打开本应用数据目录</ElButton></section></template>
